ValidationRule.errorConditionFormula:
OR(
  AND(
    NOT(ISBLANK(ContactoP__c)),
    OR(
      ISBLANK(ContactoP__r.Email),
      NOT(REGEX(ContactoP__r.Email,"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))
    )
  ),
  AND(
    NOT(ISBLANK(UsuarioP__c)),
    OR(
      ISBLANK(UsuarioP__r.Email),
      NOT(REGEX(UsuarioP__r.Email,"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$"))
    )
  )
)
